"""Base verifier class for transaction verification."""
from abc import ABC, abstractmethod
from typing import Dict, Any


class BaseVerifier(ABC):
    """Abstract base class for all verifiers."""

    def __init__(self, config):
        self.config = config

    @abstractmethod
    def verify(self, transaction, context: Dict[str, Any]):
        """Verify a transaction."""
        pass

"""Transaction data models."""
from dataclasses import dataclass
from typing import Optional, Dict, Any
from datetime import datetime


@dataclass
class Transaction:
    """Represents a financial transaction."""
    id: str
    amount: float
    currency: str = "USD"
    payment_method: str = "credit_card"
    description: Optional[str] = None
    customer_id: Optional[str] = None
    merchant_id: Optional[str] = None
    timestamp: Optional[datetime] = None
    metadata: Optional[Dict[str, Any]] = None

    def __post_init__(self):
        if self.timestamp is None:
            self.timestamp = datetime.utcnow()
        if self.metadata is None:
            self.metadata = {}


@dataclass
class VerificationStatus:
    """Result of a verification check."""
    status: str  # "APPROVED", "REJECTED", "PENDING", "ERROR"
    details: Optional[Dict[str, Any]] = None
    verifier: Optional[str] = None

    def __post_init__(self):
        if self.details is None:
            self.details = {}

"""Configuration management for transaction service."""
from typing import Any, Dict, Optional


class TransactionConfig:
    """Configuration class for transaction verification service."""

    DEFAULT_CONFIG = {
        'fraud.threshold': 0.7,
        'fraud.enable_ml_model': True,
        'fraud.ml_model_path': '/models/fraud_model.pkl',
        'rate_limit.requests_per_minute': 60,
        'rate_limit.enabled': True,
    }

    def __init__(self, config: Optional[Dict[str, Any]] = None):
        """Initialize configuration with optional overrides."""
        self._config = {**self.DEFAULT_CONFIG, **(config or {})}

    def get(self, key: str, default: Any = None) -> Any:
        """Get a configuration value by key."""
        return self._config.get(key, default)

    def set(self, key: str, value: Any) -> None:
        """Set a configuration value."""
        self._config[key] = value

    def to_dict(self) -> Dict[str, Any]:
        """Return configuration as dictionary."""
        return dict(self._config)
